import{_ as s,C as r,o as n,c as l,a3 as e,b as o,w as i,a as m,E as h,a4 as p}from"./chunks/framework.BvvarXmc.js";const u="/screenshots/pembayaran.png",f=JSON.parse('{"title":"Menetapkan Tarif SPP & Pos Tagihan","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-keuangan/setting-tagihan.md","filePath":"panduan-keuangan/setting-tagihan.md","lastUpdated":null}'),g={name:"panduan-keuangan/setting-tagihan.md"};function d(b,a,k,c,T,P){const t=r("Mermaid");return n(),l("div",null,[a[1]||(a[1]=e('<h1 id="menetapkan-tarif-spp-pos-tagihan" tabindex="-1">Menetapkan Tarif SPP &amp; Pos Tagihan <a class="header-anchor" href="#menetapkan-tarif-spp-pos-tagihan" aria-label="Permalink to &quot;Menetapkan Tarif SPP &amp; Pos Tagihan&quot;">​</a></h1><p>Sebelum siswa atau orang tua dapat melakukan pembayaran di loket maupun via online, Bendahara Sekolah harus membuat pos pembayaran dan menentukan nominal tagihan per kelas.</p><hr><h2 id="tampilan-manajemen-tagihan-pembayaran" tabindex="-1">Tampilan Manajemen Tagihan &amp; Pembayaran <a class="header-anchor" href="#tampilan-manajemen-tagihan-pembayaran" aria-label="Permalink to &quot;Tampilan Manajemen Tagihan &amp; Pembayaran&quot;">​</a></h2><p><img src="'+u+'" alt="Manajemen Tagihan"></p><hr><h2 id="_1-memahami-2-jenis-pos-pembayaran" tabindex="-1">1. Memahami 2 Jenis Pos Pembayaran <a class="header-anchor" href="#_1-memahami-2-jenis-pos-pembayaran" aria-label="Permalink to &quot;1. Memahami 2 Jenis Pos Pembayaran&quot;">​</a></h2><p>Sistem membedakan pos tagihan menjadi 2 kategori:</p><ol><li><strong>Tagihan Bulanan (SPP)</strong>: Tagihan rutin setiap bulan selama 12 bulan (Juli sampai Juni).</li><li><strong>Tagihan Bebas / Non-Bulanan</strong>: Tagihan yang dapat dicicil bertahap sesuai kemampuan siswa (contoh: Uang Gedung/Pangkal, Biaya Seragam, Karyawisata, Ujian).</li></ol><hr><h2 id="_2-alur-membuat-pos-tagihan-baru" tabindex="-1">2. Alur Membuat Pos Tagihan Baru <a class="header-anchor" href="#_2-alur-membuat-pos-tagihan-baru" aria-label="Permalink to &quot;2. Alur Membuat Pos Tagihan Baru&quot;">​</a></h2>',11)),(n(),o(p,null,{default:i(()=>[h(t,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20Tambah%20Pos%20Tagihan%22%5D%20--%3E%20B%5B%222.%20Pilih%20Tipe%20(Bulanan%20%2F%20Bebas)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Tetapkan%20Tarif%20per%20Kelas%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Terapkan%20Massal%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Tagihan%20Muncul%20di%20Akun%20Siswa%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="langkah-langkah" tabindex="-1">Langkah-langkah: <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah:&quot;">​</a></h3><ol><li>Buka menu <strong>Keuangan</strong> <strong>Pos Tagihan &amp; Pembayaran</strong>.</li><li>Klik tombol <strong><code>+ Tambah Pos Tagihan</code></strong>.</li><li>Masukkan nama pos (contoh: <em>SPP Tahun Ajaran 2026/2027</em>).</li><li>Pilih tipe pos pembayaran: <strong>Bulanan</strong> atau <strong>Bebas</strong>.</li><li>Klik <strong><code>Simpan Pos</code></strong>.</li></ol><hr><h2 id="_3-menetapkan-tarif-nominal-tagihan" tabindex="-1">3. Menetapkan Tarif Nominal Tagihan <a class="header-anchor" href="#_3-menetapkan-tarif-nominal-tagihan" aria-label="Permalink to &quot;3. Menetapkan Tarif Nominal Tagihan&quot;">​</a></h2><ol><li>Pada pos pembayaran yang baru dibuat, klik tombol <strong><code>Atur Tarif</code></strong>.</li><li>Pilih rombel kelas target (misal: <em>Kelas 7 - AL FUQON</em>).</li><li>Masukkan nominal rupiah (misal: <code>Rp 350.000 / bulan</code>).</li><li>Klik tombol <strong><code>Terapkan ke Seluruh Siswa di Kelas Ini</code></strong>.</li><li>Sistem otomatis membuatkan 12 kartu tagihan bulanan pada setiap akun siswa di rombel tersebut.</li></ol><div class="tip custom-block"><p class="custom-block-title">Pengaturan Tarif Khusus Beasiswa</p><p>Jika ada siswa tertentu yang memperoleh potongan beasiswa 50% atau beasiswa prestasi penuh (gratis):</p><ol><li>Buka tab <strong>Tarif Khusus per Siswa</strong>.</li><li>Cari nama siswa penerima beasiswa.</li><li>Ubah nominal sesuai ketentuan beasiswa lalu simpan.</li></ol></div>',6))])}const B=s(g,[["render",d]]);export{f as __pageData,B as default};
